INSERT INTO `app_settings` (`id`, `admin_name`, `app_name`, `tagline`, `description`, `google_play_url`, `privacy_policy`, `terms_conditions`, `support_email`, `support_phone`, `about`, `created_at`, `updated_at`, `enable_all_prompts_for_new_app`, `minimum_supported_version_code`, `rollout_percentage`) VALUES
(2, 'akmalcbm', 'PicPose: AI Prompts Book & Photography Guide', 'Daily AI prompts, pose ideas & photography tips for stunning visuals.', 'PicPose helps creators, photographers & AI artists with daily pose ideas, AI prompts & photography guides. Whether you’re a beginner or a pro, find inspiration to capture perfect shots & generate stunning AI visuals.\r\n⚆ AI prompts for photography\r\n⚆ Best pose ideas for photoshoot\r\n⚆ AI art prompts & guides\r\n⚆ Creative photography tips\r\n⚆ AI generated photography ideas\r\n⚆ Pose guide for models & creators\r\n⚆ PicPose AI prompts and Pose Guides', 'Google Play URL Here', '<div class=\"privacy-container\">\n    <h1 style=\"color: var(--primary-color); font-size: 28px; margin-bottom: 20px; text-align: center; border-bottom: 2px solid var(--border-color); padding-bottom: 15px;\">Privacy Policy</h1>\n    \n    <div style=\"text-align: center; margin-bottom: 30px; padding: 15px; background-color: var(--card-bg); border-radius: 10px;\">\n        <h2 style=\"color: var(--accent-color); font-size: 22px; margin-bottom: 10px;\">PicPose: AI Prompts Book</h2>\n        <p style=\"color: var(--text-color); font-size: 16px; margin-bottom: 5px;\"><strong>Last Updated:</strong> 09 December 2025</p>\n    </div>\n    \n    <p style=\"font-size: 17px; line-height: 1.6; margin-bottom: 25px; color: var(--text-color); padding: 20px; background-color: var(--card-bg); border-radius: 8px; border-left: 4px solid var(--primary-color);\">\n        Welcome to <strong>PicPose: AI Prompts Book</strong> (\"PicPose\", \"we\", \"our\", or \"us\").<br>\n        We are committed to protecting your privacy. This Privacy Policy explains how we collect, use, and safeguard your information when you use our mobile application PicPose: AI Prompts Book.\n    </p>\n    \n    <div style=\"text-align: center; margin: 30px 0; padding: 20px; background: var(--gradient-bg); border-radius: 12px;\">\n        <p style=\"font-size: 18px; color: var(--text-color); font-weight: bold;\">\n            By using our app, you agree to the practices described in this Privacy Policy.\n        </p>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">1. Information We Collect</h2>\n    \n    <p style=\"font-size: 16px; line-height: 1.6; margin-bottom: 20px; color: var(--text-color);\">\n        We aim to collect minimal user data, only what is necessary to provide a smooth experience.\n    </p>\n    \n    <h3 style=\"color: var(--highlight-color); font-size: 20px; margin: 25px 0 10px 0;\">1.1 Information You Provide</h3>\n    \n    <div style=\"background-color: var(--card-bg); padding: 20px; border-radius: 8px; margin-bottom: 20px; border-left: 4px solid var(--highlight-color);\">\n        <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 15px;\">\n            <strong>User Account Details (optional):</strong> If you sign in using Google, Facebook, or other platforms, we may receive basic profile information such as:\n        </p>\n        <ul style=\"list-style-type: none; padding: 0; margin: 0 0 15px 0;\">\n            <li style=\"margin-bottom: 10px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color);\">•</span> Name\n            </li>\n            <li style=\"margin-bottom: 10px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color);\">•</span> Email address\n            </li>\n            <li style=\"margin-bottom: 10px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color);\">•</span> Profile photo\n            </li>\n        </ul>\n        <p style=\"font-size: 16px; color: var(--text-color);\">\n            This information is used only to personalize your app experience.\n        </p>\n    </div>\n    \n    <h3 style=\"color: var(--highlight-color); font-size: 20px; margin: 25px 0 10px 0;\">1.2 Automatically Collected Information</h3>\n    \n    <div style=\"background-color: var(--card-bg); padding: 20px; border-radius: 8px; margin-bottom: 20px; border-left: 4px solid var(--highlight-color);\">\n        <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 15px;\">\n            When you use PicPose, we may automatically collect:\n        </p>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 15px; margin-bottom: 15px;\">\n            <div style=\"padding: 12px; background-color: var(--feature-bg-1); border-radius: 6px; color: var(--text-color);\">\n                <span style=\"color: var(--feature-color-1); margin-right: 8px;\">📱</span> Device information (device model, OS version)\n            </div>\n            <div style=\"padding: 12px; background-color: var(--feature-bg-2); border-radius: 6px; color: var(--text-color);\">\n                <span style=\"color: var(--feature-color-2); margin-right: 8px;\">📊</span> App activity data (features used, screens visited)\n            </div>\n            <div style=\"padding: 12px; background-color: var(--feature-bg-3); border-radius: 6px; color: var(--text-color);\">\n                <span style=\"color: var(--feature-color-3); margin-right: 8px;\">📈</span> Log data (crashes, performance events)\n            </div>\n            <div style=\"padding: 12px; background-color: var(--feature-bg-4); border-radius: 6px; color: var(--text-color);\">\n                <span style=\"color: var(--feature-color-4); margin-right: 8px;\">🔍</span> Anonymous analytics information\n            </div>\n        </div>\n        <p style=\"font-size: 16px; color: var(--text-color);\">\n            This data helps us improve app performance and user experience.\n        </p>\n    </div>\n    \n    <h3 style=\"color: var(--highlight-color); font-size: 20px; margin: 25px 0 10px 0;\">1.3 Photos & Media</h3>\n    \n    <div style=\"background-color: var(--success-bg); padding: 20px; border-radius: 8px; margin-bottom: 20px; border-left: 4px solid var(--success-color);\">\n        <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 15px;\">\n            <strong>PicPose does not access your camera or photo gallery</strong> unless you voluntarily use features that require image selection.\n        </p>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 15px; margin: 20px 0;\">\n            <div style=\"text-align: center; padding: 15px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n                <div style=\"font-size: 30px; color: var(--primary-color); margin-bottom: 10px;\">❌</div>\n                <strong>Do not store</strong> your photos on our servers\n            </div>\n            <div style=\"text-align: center; padding: 15px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n                <div style=\"font-size: 30px; color: var(--primary-color); margin-bottom: 10px;\">🤖</div>\n                <strong>Do not use</strong> your photos for AI training\n            </div>\n            <div style=\"text-align: center; padding: 15px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n                <div style=\"font-size: 30px; color: var(--primary-color); margin-bottom: 10px;\">🔒</div>\n                <strong>Do not share</strong> your images with third parties\n            </div>\n        </div>\n        <p style=\"font-size: 16px; color: var(--text-color); padding: 15px; background-color: var(--feature-bg-7); border-radius: 6px; margin-top: 15px;\">\n            <strong>Your selected images stay on your device.</strong>\n        </p>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">2. How We Use Your Information</h2>\n    \n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 15px; margin-bottom: 30px;\">\n        <div style=\"padding: 20px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <div style=\"font-size: 24px; color: var(--primary-color); margin-bottom: 10px;\">🎨</div>\n            <strong>Provide AI prompts, pose ideas, and creative photography guides</strong>\n        </div>\n        <div style=\"padding: 20px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <div style=\"font-size: 24px; color: var(--primary-color); margin-bottom: 10px;\">⚡</div>\n            <strong>Improve app functionality and performance</strong>\n        </div>\n        <div style=\"padding: 20px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <div style=\"font-size: 24px; color: var(--primary-color); margin-bottom: 10px;\">👤</div>\n            <strong>Personalize your experience</strong>\n        </div>\n        <div style=\"padding: 20px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <div style=\"font-size: 24px; color: var(--primary-color); margin-bottom: 10px;\">🔔</div>\n            <strong>Send notifications (if enabled)</strong>\n        </div>\n        <div style=\"padding: 20px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <div style=\"font-size: 24px; color: var(--primary-color); margin-bottom: 10px;\">📈</div>\n            <strong>Monitor analytics to improve content quality</strong>\n        </div>\n        <div style=\"padding: 20px; background-color: var(--card-bg); border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <div style=\"font-size: 24px; color: var(--primary-color); margin-bottom: 10px;\">📢</div>\n            <strong>Display ads (if applicable)</strong>\n        </div>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">3. Third-Party Services</h2>\n    \n    <p style=\"font-size: 16px; line-height: 1.6; margin-bottom: 20px; color: var(--text-color);\">\n        PicPose may use trusted third-party tools, such as:\n    </p>\n    \n    <h3 style=\"color: var(--highlight-color); font-size: 20px; margin: 25px 0 10px 0;\">3.1 Google Analytics / Firebase</h3>\n    \n    <div style=\"background-color: var(--card-bg); padding: 15px; border-radius: 8px; margin-bottom: 20px; border-left: 4px solid #4285F4;\">\n        <p style=\"font-size: 16px; color: var(--text-color);\">\n            Used to understand app usage and improve features.\n        </p>\n    </div>\n    \n    <h3 style=\"color: var(--highlight-color); font-size: 20px; margin: 25px 0 10px 0;\">3.2 Ad Networks (AdMob / Meta Audience Network)</h3>\n    \n    <div style=\"background-color: var(--card-bg); padding: 15px; border-radius: 8px; margin-bottom: 20px; border-left: 4px solid #FF6D01;\">\n        <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 10px;\">\n            Ads may be shown within the app. These networks may collect:\n        </p>\n        <ul style=\"list-style-type: none; padding: 0; margin: 0 0 10px 0;\">\n            <li style=\"margin-bottom: 8px; padding-left: 20px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0;\">📱</span> Advertising identifiers\n            </li>\n            <li style=\"margin-bottom: 8px; padding-left: 20px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0;\">📍</span> Approximate location\n            </li>\n            <li style=\"margin-bottom: 8px; padding-left: 20px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0;\">💻</span> Device information\n            </li>\n        </ul>\n        <p style=\"font-size: 16px; color: var(--text-color); background-color: var(--success-bg); padding: 10px; border-radius: 6px;\">\n            <strong>Ads are personalized only if you give permission through platform settings.</strong>\n        </p>\n    </div>\n    \n    <h3 style=\"color: var(--highlight-color); font-size: 20px; margin: 25px 0 10px 0;\">3.3 Social Login (Google, Facebook, etc.)</h3>\n    \n    <div style=\"background-color: var(--card-bg); padding: 15px; border-radius: 8px; margin-bottom: 20px; border-left: 4px solid #1877F2;\">\n        <p style=\"font-size: 16px; color: var(--text-color);\">\n            If you sign in using a social platform, we receive only the information necessary for authentication.\n        </p>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">4. Data Sharing</h2>\n    \n    <div style=\"text-align: center; padding: 20px; background-color: var(--card-bg); border-radius: 10px; margin-bottom: 25px;\">\n        <p style=\"font-size: 20px; color: var(--text-color); margin-bottom: 15px;\">\n            <span style=\"font-size: 30px; color: var(--primary-color);\">❌</span><br>\n            <strong>We do not sell, rent, or trade your personal information.</strong>\n        </p>\n    </div>\n    \n    <div style=\"background-color: var(--card-bg); padding: 20px; border-radius: 8px; margin-bottom: 25px;\">\n        <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 15px;\">\n            <strong>We may share limited data only when required:</strong>\n        </p>\n        <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 15px;\">\n            <div style=\"padding: 15px; background-color: var(--feature-bg-1); border-radius: 6px;\">\n                <span style=\"color: var(--feature-color-1); font-size: 20px; margin-right: 10px;\">⚖️</span>\n                To comply with legal requests\n            </div>\n            <div style=\"padding: 15px; background-color: var(--feature-bg-2); border-radius: 6px;\">\n                <span style=\"color: var(--feature-color-2); font-size: 20px; margin-right: 10px;\">🛡️</span>\n                To prevent fraud or misuse\n            </div>\n            <div style=\"padding: 15px; background-color: var(--feature-bg-3); border-radius: 6px;\">\n                <span style=\"color: var(--feature-color-3); font-size: 20px; margin-right: 10px;\">🤝</span>\n                With service providers who help run the app (analytics, ads) — but they cannot use your data for their own purposes\n            </div>\n        </div>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">5. Data Security</h2>\n    \n    <div style=\"background-color: var(--card-bg); padding: 20px; border-radius: 8px; margin-bottom: 25px; border-left: 4px solid var(--success-color);\">\n        <div style=\"text-align: center; margin-bottom: 15px;\">\n            <span style=\"font-size: 40px; color: var(--primary-color);\">🔒</span>\n        </div>\n        <p style=\"font-size: 16px; color: var(--text-color); text-align: center;\">\n            We use industry-standard measures to protect your data.<br>\n            However, no method of transmission over the internet is fully secure. We cannot guarantee absolute protection.\n        </p>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">6. Children\'s Privacy</h2>\n    \n    <div style=\"background-color: var(--card-bg); padding: 20px; border-radius: 8px; margin-bottom: 25px; border-left: 4px solid #FF9800;\">\n        <div style=\"display: flex; align-items: center; gap: 15px; margin-bottom: 15px;\">\n            <div style=\"font-size: 40px; color: #FF9800;\">👶</div>\n            <div>\n                <p style=\"font-size: 18px; color: var(--text-color); margin: 0; font-weight: bold;\">\n                    PicPose is not intended for children under 13.\n                </p>\n            </div>\n        </div>\n        <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 10px;\">\n            We do not knowingly collect information from children.\n        </p>\n        <p style=\"font-size: 16px; color: var(--text-color); padding: 10px; background-color: var(--success-bg); border-radius: 6px;\">\n            If we become aware of such data, we will delete it.\n        </p>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 30px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">7. Your Rights & Choices</h2>\n    \n    <p style=\"font-size: 16px; color: var(--text-color); margin-bottom: 20px;\">\n        Depending on your region, you may have rights such as:\n    </p>\n    \n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 12px; margin-bottom: 25px;\">\n        <div style=\"padding: 12px; background-color: var(--feature-bg-1); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-1); margin-right: 8px;\">🗑️</span> Requesting deletion of your account data\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-2); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-2); margin-right: 8px;\">✏️</span> Updating personal information\