--border-color: #E0E0E0;\n    --card-bg: #f8f9fa;\n    --card-shadow: 0 2px 5px rgba(0,0,0,0.1);\n    --gradient-bg: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);\n    --success-bg: #E8F5E9;\n    \n    /* Feature colors - Light mode */\n    --feature-bg-1: #FFF3E0;\n    --feature-color-1: #FF9800;\n    --feature-bg-2: #E8EAF6;\n    --feature-color-2: #3F51B5;\n    --feature-bg-3: #E0F2F1;\n    --feature-color-3: #009688;\n    --feature-bg-4: #FCE4EC;\n    --feature-color-4: #E91E63;\n    --feature-bg-5: #F3E5F5;\n    --feature-color-5: #9C27B0;\n    --feature-bg-6: #FFF8E1;\n    --feature-color-6: #FFC107;\n    --feature-bg-7: #E8F5E9;\n    --feature-color-7: #4CAF50;\n    \n    /* CTA gradient */\n    --cta-gradient: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%);\n}\n\n/* Dark Mode Variables */\n@media (prefers-color-scheme: dark) {\n    :root {\n        --bg-color: #121212;\n        --text-color: #e0e0e0;\n        --primary-color: #81C784;\n        --accent-color: #64B5F6;\n        --highlight-color: #FF8A65;\n        --success-color: #81C784;\n        --border-color: #444444;\n        --card-bg: #1e1e1e;\n        --card-shadow: 0 2px 10px rgba(0,0,0,0.3);\n        --gradient-bg: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);\n        --success-bg: #1B5E20;\n        \n        /* Feature colors - Dark mode */\n        --feature-bg-1: #332208;\n        --feature-color-1: #FFB74D;\n        --feature-bg-2: #1A237E;\n        --feature-color-2: #7986CB;\n        --feature-bg-3: #004D40;\n        --feature-color-3: #4DB6AC;\n        --feature-bg-4: #880E4F;\n        --feature-color-4: #F48FB1;\n        --feature-bg-5: #4A148C;\n        --feature-color-5: #BA68C8;\n        --feature-bg-6: #FF8F00;\n        --feature-color-6: #FFD54F;\n        --feature-bg-7: #1B5E20;\n        --feature-color-7: #81C784;\n        \n        /* CTA gradient - Dark mode */', 'picposeapp@gmail.com', '+91 7007515828', '<div class=\"about-container\">\n    <h1 style=\"color: var(--primary-color); font-size: 28px; margin-bottom: 15px; text-align: center;\">About PicPose</h1>\n    \n    <p style=\"font-size: 18px; line-height: 1.6; margin-bottom: 20px; color: var(--text-color);\">\n        <strong style=\"color: var(--accent-color);\">Unlock your creativity with PicPose: AI Prompts Book & Photography Guide</strong>, \n        the ultimate app for photographers, creators, influencers, and AI artists. \n        Whether you\'re capturing real photos or generating AI visuals, PicPose gives you \n        daily AI prompts, posing ideas, creative photography tips, model pose guides, \n        and aesthetic concepts—all in one place.\n    </p>\n    \n    <p style=\"font-size: 16px; line-height: 1.5; margin-bottom: 25px; background-color: var(--card-bg); padding: 15px; border-radius: 8px; border-left: 4px solid var(--highlight-color); color: var(--text-color);\">\n        Perfect for beginners, professionals, and anyone who loves photography or AI art.\n    </p>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 25px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">✨ What PicPose Offers</h2>\n    \n    <div style=\"background: var(--gradient-bg); padding: 20px; border-radius: 10px; margin-bottom: 25px;\">\n        <ul style=\"list-style-type: none; padding: 0; margin: 0;\">\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">Daily AI Prompts</strong> – Get fresh, unique, and trending AI prompts for Midjourney, DALL·E, Stable Diffusion, Leonardo AI, and more.\n            </li>\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">Photography Pose Ideas</strong> – Explore hundreds of pose references for men, women, couples, kids, friends, and fashion shoots.\n            </li>\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">AI Art Prompt Book</strong> – Discover powerful prompt styles for portraits, cinematic shots, fantasy art, landscapes, and concept visuals.\n            </li>\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">Photography Tips & Guides</strong> – Learn lighting setups, angles, composition tricks, and creative storytelling ideas.\n            </li>\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">Model Pose Guide</strong> – Perfect for influencers, models, and photographers looking to elevate their photoshoot game.\n            </li>\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">Creative Inspiration</strong> – Get ideas for Instagram photos, reels, modeling, lifestyle shoots, and professional portfolio building.\n            </li>\n            <li style=\"margin-bottom: 12px; padding-left: 25px; position: relative; color: var(--text-color);\">\n                <span style=\"position: absolute; left: 0; color: var(--primary-color); font-weight: bold;\">✔</span>\n                <strong style=\"color: var(--text-color);\">AI Generated Photo Ideas</strong> – Smartly curated inspiration using AI for every theme and aesthetic.\n            </li>\n        </ul>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 25px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">📸 Why PicPose?</h2>\n    \n    <p style=\"font-size: 17px; margin-bottom: 15px; color: var(--text-color);\">\n        PicPose helps you:\n    </p>\n    \n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 15px; margin-bottom: 25px;\">\n        <div style=\"background: var(--card-bg); padding: 15px; border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <span style=\"color: var(--highlight-color); font-size: 20px;\">🔹</span>\n            <strong style=\"color: var(--text-color);\">Find the perfect pose</strong> for every situation\n        </div>\n        <div style=\"background: var(--card-bg); padding: 15px; border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <span style=\"color: var(--highlight-color); font-size: 20px;\">🔹</span>\n            <strong style=\"color: var(--text-color);\">Improve your photography skills</strong> with easy guides\n        </div>\n        <div style=\"background: var(--card-bg); padding: 15px; border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <span style=\"color: var(--highlight-color); font-size: 20px;\">🔹</span>\n            <strong style=\"color: var(--text-color);\">Generate stunning AI images</strong> with ready-made prompts\n        </div>\n        <div style=\"background: var(--card-bg); padding: 15px; border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <span style=\"color: var(--highlight-color); font-size: 20px;\">🔹</span>\n            <strong style=\"color: var(--text-color);\">Get daily inspiration</strong> for creative shoots\n        </div>\n        <div style=\"background: var(--card-bg); padding: 15px; border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <span style=\"color: var(--highlight-color); font-size: 20px;\">🔹</span>\n            <strong style=\"color: var(--text-color);\">Boost your social media photos</strong> with trending ideas\n        </div>\n        <div style=\"background: var(--card-bg); padding: 15px; border-radius: 8px; box-shadow: var(--card-shadow);\">\n            <span style=\"color: var(--highlight-color); font-size: 20px;\">🔹</span>\n            <strong style=\"color: var(--text-color);\">Save time brainstorming</strong> concepts for your next photoshoot\n        </div>\n    </div>\n    \n    <p style=\"font-size: 16px; line-height: 1.6; margin-bottom: 25px; padding: 15px; background-color: var(--success-bg); border-radius: 8px; border-left: 4px solid var(--success-color); color: var(--text-color);\">\n        Whether you\'re a photographer, content creator, AI artist, or casual user—PicPose makes creativity simple and fun.\n    </p>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 25px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">🌟 Top Features</h2>\n    \n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 10px; margin-bottom: 25px;\">\n        <div style=\"padding: 12px; background-color: var(--feature-bg-1); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-1); margin-right: 8px;\">•</span> Huge library of AI prompts for photography & art\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-2); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-2); margin-right: 8px;\">•</span> Best pose ideas for photoshoots\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-3); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-3); margin-right: 8px;\">•</span> Creative photography tips and beginner-friendly guides\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-4); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-4); margin-right: 8px;\">•</span> Sorted categories for effortless discovery\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-5); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-5); margin-right: 8px;\">•</span> Save your favorite prompts and poses\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-6); border-radius: 6px; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-6); margin-right: 8px;\">•</span> Daily updates for endless inspiration\n        </div>\n        <div style=\"padding: 12px; background-color: var(--feature-bg-7); border-radius: 6px; grid-column: span 2; color: var(--text-color);\">\n            <span style=\"color: var(--feature-color-7); margin-right: 8px;\">•</span> Lightweight, smooth, and fast app experience\n        </div>\n    </div>\n    \n    <h2 style=\"color: var(--accent-color); font-size: 24px; margin: 25px 0 15px 0; border-bottom: 2px solid var(--border-color); padding-bottom: 8px;\">🎯 Who Is PicPose For?</h2>\n    \n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; margin-bottom: 25px;\">\n        <div style=\"text-align: center; padding: 15px; background: var(--audience-gradient-1); color: white; border-radius: 10px;\">\n            <div style=\"font-size: 40px; margin-bottom: 10px;\">📷</div>\n            <strong>Photographers</strong><br>(beginner to pro)\n        </div>\n        <div style=\"text-align: center; padding: 15px; background: var(--audience-gradient-2); color: white; border-radius: 10px;\">\n            <div style=\"font-size: 40px; margin-bottom: 10px;\">🌟</div>\n            <strong>Instagram influencers</strong><br>& content creators\n        </div>\n        <div style=\"text-align: center; padding: 15px; background: var(--audience-gradient-3); color: white; border-radius: 10px;\">\n            <div style=\"font-size: 40px; margin-bottom: 10px;\">👗</div>\n            <strong>Models, fashion photographers</strong><br>& stylists\n        </div>\n        <div style=\"text-align: center; padding: 15px; background: var(--audience-gradient-4); color: white; border-radius: 10px;\">\n            <div style=\"font-size: 40px; margin-bottom: 10px;\">🤖</div>\n            <strong>AI artists</strong><br>using Midjourney / DALL·E / SDXL\n        </div>\n        <div style=\"text-align: center; padding: 15px; background: var(--audience-gradient-5); color: white; border-radius: 10px; grid-column: span 2;\">\n            <div style=\"font-size: 40px; margin-bottom: 10px;\">🎬</div>\n            <strong>Creators planning reels, portraits,</strong><br>cinematic shots & creative photo ideas\n        </div>\n    </div>\n    \n    <div style=\"text-align: center; padding: 30px; background: var(--cta-gradient); color: white; border-radius: 15px; margin: 30px 0;\">\n        <h2 style=\"font-size: 32px; margin-bottom: 15px; color: white;\">🚀 Create Better. Capture Smarter. Inspire Daily.</h2>\n        <p style=\"font-size: 18px; margin-bottom: 20px;\">\n            Download PicPose: AI Prompts Book & Photography Guide App today<br>\n            and transform your ideas into beautiful visuals—powered by creativity + AI!\n        </p>\n        <div style=\"font-size: 50px; margin-top: 20px;\">\n            📱✨🎨\n        </div>\n    </div>\n    \n    <div style=\"margin-top: 30px; padding: 20px; background-color: var(--card-bg); border-radius: 10px; border: 1px solid var(--border-color);\">\n        <h3 style=\"color: var(--text-color); margin-bottom: 15px; font-size: 20px;\">📞 Contact & Support</h3>\n        <p style=\"margin: 8px 0; color: var(--text-color);\"><strong>Email:</strong> picposeapp@gmail.com</p>\n        <p style=\"margin: 8px 0; color: var(--text-color);\"><strong>Phone:</strong> +91 7007515828</p>\n        <p style=\"margin: 8px 0; color: var(--text-color);\"><strong>Website:</strong> picpose.iamakmal.in</p>\n        <p style=\"margin: 8px 0; color: var(--text-color);\"><strong>Developer:</strong> Akmal</p>\n    </div>\n</div>\n\n<style>\n.about-container {\n    font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, sans-serif;\n    max-width: 800px;\n    margin: 0 auto;\n    padding: 20px;\n}\n\n/* Light Mode Variables (Default) */\n:root {\n    --bg-color: #ffffff;\n    --text-color: #333333;\n    --primary-color: #4CAF50;\n    --accent-color: #2196F3;\n    --highlight-color: #FF5722;\n    --success-color: #4CAF50;\n    --border-color: #E0E0E0;\n    --card-bg: #f8f9fa;\n    --card-shadow: 0 2px 5px rgba(0,0,0,0.1);\n    --gradient-bg: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);\n    --success-bg: #E8F5E9;\n    \n    /* Feature colors - Light mode */\n    --feature-bg-1: #FFF3E0;\n    --feature-color-1: #FF9800;\n    --feature-bg-2: #E8EAF6;\n    --feature-color-2: #3F51B5;\n    --feature-bg-3: #E0F2F1;\n    --feature-color-3: #009688;\n    --feature-bg-4: #FCE4EC;\n    --feature-color-4: #E91E63;\n    --feature-bg-5: #F3E5F5;\n    --feature-color-5: #9C27B0;\n    --feature-bg-6: #FFF8E1;\n    --feature-color-6: #FFC107;\n    --feature-bg-7: #E8F5E9;\n    --feature-color-7: #4CAF50;\n    \n    /* Audience gradients - Light mode */\n    --audience-gradient-1: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n    --audience-gradient-2: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);\n    --audience-gradient-3: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);\n    --audience-gradient-4: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%);\n    --audience-gradient-5: linear-gradient(135deg, #fa709a 0%, #fee140 100%);\n    \n    /* CTA gradient */\n    --cta-gradient: linear-gradient(135deg, #6a11cb 0%, #2575fc 100%);\n}\n\n/* Dark Mode Variables */\n@media (prefers-color-scheme: dark) {\n    :root {\n        --bg-color: #121212;\n        --text-color: #e0e0e0;\n        --primary-color: #81C784;\n        --accent-color: #64B5F6;\n        --highlight-color: #FF8A65;\n        --success-color: #81C784;\n        --border-color: #444444;\n        --card-bg: #1e1e1e;\n        --card-shadow: 0 2px 10px rgba(0,0,0,0.3);\n        --gradient-bg: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);\n        --success-bg: #1B5E20;\n        \n        /* Feature colors - Dark mode */\n        --feature-bg-1: #332208;\n        --feature-color-1: #FFB74D;\n        --feature-bg-2: #1A237E;\n        --feature-color-2: #7986CB;\n        --feature-bg-3: #004D40;\n        --feature-color-3: #4DB6AC;\n        --feature-bg-4: #880E4F;\n        --feature-color-4: #F48FB1;\n        --feature-bg-5: #4A148C;\n        --feature-color-5: #BA68C8;\n        --feature-bg-6: #FF8F00;\n        --feature-color-6: #FFD54F;\n        --feature-bg-7: #1B5E20;\n        --feature-color-7: #81C784;\n        \n        /* Audience gradients - Dark mode (darker versions) */\n        --audience-gradient-1: linear-gradient(135deg, #5a67d8 0%, #805ad5 100%);\n        --audience-gradient-2: linear-gradient(135deg, #d53f8c 0%, #ed64a6 100%);\n        --audience-gradient-3: linear-gradient(135deg, #3182ce 0%, #63b3ed 100%);\n        --audience-gradient-4: linear-gradient(135deg, #38a169 0%, #68d391 100%);\n        --audience-gradient-5: linear-gradient(135deg, #dd6b20 0%, #ed8936 100%);\n        \n        /* CTA gradient - Dark mode */\n        --cta-gradient: linear-gradient(135deg, #553c9a 0%, #2c5282 100%);\n    }\n    \n    .about-container {\n        background-color: var(--bg-color);\n    }\n}\n\n/* Apply background color */\n.about-container {\n    background-color: var(--bg-color);\n    color: var(--text-color);\n}\n\n@media (max-width: 768px) {\n    .about-container {\n        padding: 15px;\n    }\n    \n    h1 { font-size: 24px !important; }\n    h2 { font-size: 20px !important; }\n    \n    .about-container div[style*=\"grid-template-columns\"] {\n        grid-template-columns: 1fr !important;\n    }\n}\n\n/* Fallback for browsers that don\'t support prefers-color-scheme */\n@media (prefers-color-scheme: dark) {\n    body {\n        background-color: var(--bg-color);\n        color: var(--text-color);\n    }\n}\n</style>', '2025-10-27 10:32:01', '2026-02-15 11:02:21', 0, 999999, 0);
