INSERT INTO `daily_tips` (`id`, `tip_text`, `is_active`, `display_order`, `created_at`, `updated_at`) VALUES
(1, 'Use specific descriptive words in your prompts for better AI results! 🎯', 1, 0, '2025-09-17 11:24:18', '2026-02-03 19:32:36'),
(2, 'Try combining different art styles like \'watercolor meets cyberpunk\' for unique effects! 🎨', 1, 1, '2025-09-17 11:24:30', '2026-02-03 19:32:45'),
(3, 'Add lighting conditions like \'golden hour\' or \'dramatic shadows\' to enhance your images! ✨', 1, 2, '2025-09-17 11:24:43', '2026-02-03 19:32:54'),
(4, 'Specify camera angles like \'bird\'s eye view\' or \'close-up portrait\' for better composition! 📸', 1, 3, '2025-09-17 11:24:56', '2026-02-03 19:33:11'),
(5, 'Use emotion words like \'serene\', \'energetic\', or \'mysterious\' to set the mood! 😊', 1, 4, '2025-09-17 11:25:07', '2026-02-03 19:33:20'),
(8, 'Create Space Between Arms & Body: \r\nKeep a little gap between your arms and torso to look slimmer and more natural.', 1, 30, '2026-02-10 07:14:52', NULL),
(9, 'Slightly Bend Your Elbows: \r\nStraight arms look stiff. A soft bend adds relaxation and confidence.', 1, 30, '2026-02-10 07:16:30', '2026-02-10 07:17:04'),
(10, 'Hands on Hips or in Pockets: \r\nLightly rest your hands to avoid awkward poses and add style.', 1, 30, '2026-02-10 07:17:31', NULL),
(11, 'Cross Ankles While Sitting: \r\nCrossed ankles create a graceful, polished seated pose.', 1, 30, '2026-02-10 07:17:58', NULL),
(12, 'Shift Weight to One Leg: \r\nPutting weight on one leg adds curves and a natural flow.', 1, 30, '2026-02-10 07:18:16', NULL),
(13, 'Turn Toes Slightly Inward: \r\nA subtle inward toe angle gives a casual, friendly vibe.', 1, 30, '2026-02-10 07:18:46', NULL),
(14, 'Turn Toes Slightly Inward: \r\nA subtle inward toe angle gives a casual, friendly vibe.', 1, 30, '2026-02-10 07:18:47', NULL),
(15, 'Lower Your Chin Slightly: \r\nA small chin drop defines your jawline beautifully.', 1, 30, '2026-02-10 07:19:02', NULL),
(16, 'Soft Eye Squint for Real Smiles: \r\nA gentle squint makes your smile look authentic and confident.', 1, 30, '2026-02-10 07:19:18', NULL),
(17, 'Laugh Right Before the Shot: \r\nReal laughter brings life and energy into your photos.', 1, 30, '2026-02-10 07:19:31', NULL),
(18, 'Relax Your Face and Body: \r\nTension shows on camera. Stay loose and natural.', 1, 30, '2026-02-10 07:19:43', NULL),
(19, 'Bring Ears Slightly Forward: \r\nThis trick elongates the neck and avoids double chin.', 1, 30, '2026-02-10 07:19:55', NULL),
(20, 'Tongue Behind Teeth When Smiling: \r\nPrevents a gummy smile and keeps your smile smooth.', 1, 30, '2026-02-10 07:20:07', NULL),
(21, 'Turn Your Body 45 Degrees: \r\nAngling your body makes you look slimmer and stylish.', 1, 30, '2026-02-10 07:20:18', NULL),
(22, 'Fix Your Posture: \r\nStand tall, shoulders back — confidence shows instantly.', 1, 30, '2026-02-10 07:20:34', NULL),
(23, 'Drop Your Shoulders: \r\nRelaxed shoulders create an elegant neck line.', 1, 30, '2026-02-10 07:20:47', NULL),
(24, 'Lean Slightly Forward: \r\nA small lean adds depth and engagement to photos.', 1, 30, '2026-02-10 07:20:58', NULL),
(25, 'Slightly Bend the Standing Leg: \r\nSoft bends look more natural than locked knees.', 1, 30, '2026-02-10 07:21:09', NULL),
(26, 'Create Triangles in Group Photos\r\nDifferent heights make group shots dynamic and balanced.', 1, 30, '2026-02-10 07:21:19', NULL),
(27, 'Use Natural Touch in Group Shots: \r\nLight shoulder or arm contact adds warmth and connection.', 1, 30, '2026-02-10 07:21:31', NULL),
(28, 'Mix Sitting and Standing Positions: \r\nLayered poses keep group photos interesting.', 1, 30, '2026-02-10 07:21:45', NULL),
(29, 'Hold Camera Above Eye Level: \r\nThis angle lifts your face and sharpens features.', 1, 30, '2026-02-10 07:22:01', NULL),
(30, 'Extend Your Arm Fully for Selfies: \r\nCreates better perspective and avoids distortion.', 1, 30, '2026-02-10 07:22:15', NULL),
(31, 'Turn Your Head to Find Best Angle: \r\nEveryone has a good side — find yours.', 1, 30, '2026-02-10 07:22:26', NULL),
(32, 'Feet Shoulder-Width Apart (Men): \r\nA balanced stance gives a strong, confident look.', 1, 30, '2026-02-10 07:22:38', NULL),
(33, 'Roll Shoulders Back (Men): \r\nImproves posture and makes you look powerful.', 1, 30, '2026-02-10 07:22:52', NULL),
(34, 'Create Asymmetry with Arms (Men): \r\nDifferent arm positions feel natural and effortless.', 1, 30, '2026-02-10 07:23:06', NULL),
(35, 'Lean on an Object: \r\nWalls or chairs help you relax into candid poses.', 1, 30, '2026-02-10 07:23:18', NULL),
(36, 'Create an S-Curve (Women): \r\nA soft curve highlights natural elegance.', 1, 30, '2026-02-10 07:23:32', NULL),
(37, 'Keep Arms Slightly Away from Body: \r\nAdds definition and a slimming effect.', 1, 30, '2026-02-10 07:23:44', NULL),
(38, 'Go for a Candid Pose: \r\nNatural moments always look the best.', 1, 30, '2026-02-10 07:23:59', NULL),
(39, 'Use Clear & Descriptive Words: \r\nSpecific details give AI better direction and sharper results 🎯', 1, 0, '2026-02-10 07:28:04', NULL),
(40, 'Mix Art Styles Creatively: \r\nTry combos like “watercolor meets cyberpunk” for unique visuals 🎨', 1, 0, '2026-02-10 07:28:15', NULL),
(41, 'Add Lighting Details: \r\nUse phrases like golden hour, soft studio light, or dramatic shadows ✨', 1, 0, '2026-02-10 07:28:25', NULL),
(42, 'Mention Camera Angles: \r\nWords like close-up, wide shot, or bird’s eye view improve composition 📸', 1, 0, '2026-02-10 07:28:41', NULL),
(43, 'Include Emotions & Mood: \r\nAdd words like serene, bold, mysterious, or dreamy 😊', 1, 0, '2026-02-10 07:28:52', NULL),
(44, 'Describe Facial Expressions: \r\nMention soft smile, intense gaze, or thoughtful look for realism 😌', 1, 0, '2026-02-10 07:29:03', NULL),
(45, 'Specify Environment Clearly: \r\nTell AI where the scene is — beach, cafe, forest, studio, city 🌆', 1, 0, '2026-02-10 07:29:15', NULL),
(46, 'Use Time of Day: \r\nMorning light, sunset glow, or midnight vibes change the whole mood 🌅', 1, 0, '2026-02-10 07:29:27', NULL),
(47, 'Add Clothing & Texture Details: \r\nWords like silk dress, denim jacket, or flowing fabric add depth 👗', 1, 0, '2026-02-10 07:29:40', NULL),
(48, 'Mention Color Palette: \r\nTry warm tones, pastel colors, or high contrast for style 🎨', 1, 0, '2026-02-10 07:29:57', NULL),
(49, 'Use Action Words: \r\nWalking, laughing, turning, or sitting makes images feel alive 🚶', 1, 0, '2026-02-10 07:30:08', NULL),
(50, 'Define Background Style: \r\nClean background, blurred bokeh, or detailed scenery — be specific 🖼️', 1, 0, '2026-02-10 07:30:19', NULL),
(51, 'Mention Art Quality Level: \r\nUse terms like ultra-detailed, high resolution, or cinematic look 🎬', 1, 0, '2026-02-10 07:30:30', NULL),
(52, 'Control Realism Level: \r\nSay hyper-realistic, illustrated, or anime-style for clarity 🧠', 1, 0, '2026-02-10 07:30:41', NULL),
(53, 'Add Weather Conditions: \r\nRainy, foggy, sunny, or snowy scenes add drama 🌧️', 1, 0, '2026-02-10 07:30:53', NULL),
(54, 'Use Reference Keywords: \r\nWords like editorial photo, fashion shoot, or movie still help AI 🎥', 1, 0, '2026-02-10 07:31:05', NULL),
(55, 'Specify Focus Area: \r\nTell AI what matters most — face, eyes, outfit, or background 👀', 1, 0, '2026-02-10 07:31:20', NULL),
(56, 'Keep Prompts Structured: \r\nStart with subject → style → lighting → mood → background 🧩', 1, 0, '2026-02-10 07:31:31', NULL),
(57, 'Avoid Overloading Prompts: \r\nToo many ideas confuse AI — clarity beats quantity ✂️', 1, 0, '2026-02-10 07:31:43', NULL),
(58, 'Experiment & Refine: \r\nSmall prompt changes can unlock big visual upgrades 🚀', 1, 0, '2026-02-10 07:31:54', NULL);
